class SessionManager{constructor(){this.sessionId=this.generateSessionId(),this.sessionStartTime=Date.now(),this.sessionData={id:this.sessionId,startTime:this.sessionStartTime,postsRead:0,adClicks:0,totalReadingTime:0,pagesVisited:[],personalityType:null,deviceType:null,riskLevel:"low",status:"active"},this.maxSessionDuration=18e5,this.maxPostsPerSession=5,this.maxAdClicksPerSession=1,this.initializeSession()}initializeSession(){this.loadSessionData(),this.setupSessionMonitoring(),this.setupAutoSave()}generateSessionId(){return"session_"+Date.now()+"_"+Math.random().toString(36).substr(2,9)}loadSessionData(){try{const s=localStorage.getItem("smartAdSense_session_"+this.sessionId);if(s){const t=JSON.parse(s);this.sessionData={...this.sessionData,...t}}}catch(s){}}saveSessionData(){try{const s={...this.sessionData,lastUpdate:Date.now(),sessionDuration:this.getSessionDuration()};localStorage.setItem("smartAdSense_session_"+this.sessionId,JSON.stringify(s))}catch(s){}}setupSessionMonitoring(){this.monitoringInterval=setInterval(()=>{this.checkSessionStatus(),this.updateSessionStats()},3e4),this.forceNavigationInterval=setInterval(()=>{this.checkForceNavigation()},6e4)}setupAutoSave(){this.autoSaveInterval=setInterval(()=>{this.saveSessionData()},6e4)}checkSessionStatus(){Date.now()-this.sessionStartTime>this.maxSessionDuration?this.endSession("timeout"):this.sessionData.postsRead>=this.maxPostsPerSession?this.endSession("posts_limit"):this.sessionData.adClicks>=this.maxAdClicksPerSession?this.endSession("clicks_limit"):this.sessionData.status="active"}checkForceNavigation(){const s=Date.now()-this.sessionStartTime,t=Math.floor(s/6e4);if("mobile"===this.sessionData.deviceType){if(t>=3&&0===this.sessionData.postsRead)return void this.triggerForceNavigation("mobile_aggressive");if(t>=5&&this.sessionData.postsRead<1)return void this.triggerForceNavigation("mobile_timeout");if(t>=7)return void this.triggerForceNavigation("mobile_force")}else{if(t>=5&&0===this.sessionData.postsRead)return void this.triggerForceNavigation("desktop_timeout");if(t>=8&&this.sessionData.postsRead<2)return void this.triggerForceNavigation("desktop_insufficient");if(t>=10)return void this.triggerForceNavigation("desktop_force")}}triggerForceNavigation(s="timeout"){this.sendForceNavigationMessage(s),this.sessionData.status="force_navigation"}sendForceNavigationMessage(s="timeout"){chrome.runtime.sendMessage({action:"forceNavigation",reason:s,sessionData:{duration:this.formatDuration(this.getSessionDuration()),postsRead:this.sessionData.postsRead,adClicks:this.sessionData.adClicks,deviceType:this.sessionData.deviceType}}).catch(()=>{})}updateSessionStats(){const s=Date.now();this.sessionData.sessionDuration=s-this.sessionStartTime}recordPageVisit(s,t){const e={url:s,timestamp:Date.now(),deviceType:t.deviceType,contentLength:t.content?t.content.length:0,readingTime:t.readingTime||0};this.sessionData.pagesVisited.push(e),this.sessionData.postsRead++}recordAdClick(s){this.sessionData.adClicks++}recordReadingTime(s){this.sessionData.totalReadingTime+=s}setPersonalityType(s){this.sessionData.personalityType=s}setDeviceType(s){this.sessionData.deviceType=s}updateRiskLevel(s){this.sessionData.riskLevel=s}endSession(s){this.sessionData.status="completed",this.sessionData.endTime=Date.now(),this.sessionData.endReason=s,this.monitoringInterval&&clearInterval(this.monitoringInterval),this.autoSaveInterval&&clearInterval(this.autoSaveInterval),this.saveSessionData(),this.sendSessionCompletionMessage()}getSessionDuration(){return(this.sessionData.endTime||Date.now())-this.sessionStartTime}formatDuration(s){return`${Math.floor(s/6e4)}m ${Math.floor(s%6e4/1e3)}s`}getSessionStats(){return{id:this.sessionId,status:this.sessionData.status,duration:this.formatDuration(this.getSessionDuration()),postsRead:this.sessionData.postsRead,adClicks:this.sessionData.adClicks,totalReadingTime:this.formatDuration(this.sessionData.totalReadingTime),pagesVisited:this.sessionData.pagesVisited.length,personalityType:this.sessionData.personalityType,deviceType:this.sessionData.deviceType,riskLevel:this.sessionData.riskLevel,startTime:new Date(this.sessionStartTime).toLocaleTimeString(),endTime:this.sessionData.endTime?new Date(this.sessionData.endTime).toLocaleTimeString():null}}getSessionProgress(){const s=this.sessionData.postsRead/this.maxPostsPerSession*100,t=this.sessionData.adClicks/this.maxAdClicksPerSession*100,e=this.getSessionDuration()/this.maxSessionDuration*100;return{postsProgress:Math.min(s,100),clicksProgress:Math.min(t,100),timeProgress:Math.min(e,100),isComplete:"completed"===this.sessionData.status}}isSessionActive(){return"active"===this.sessionData.status}isSessionComplete(){return"completed"===this.sessionData.status}canReadMorePosts(){return this.sessionData.postsRead<this.maxPostsPerSession}canClickMoreAds(){return this.sessionData.adClicks<this.maxAdClicksPerSession}getRemainingPosts(){return Math.max(0,this.maxPostsPerSession-this.sessionData.postsRead)}getRemainingAdClicks(){return Math.max(0,this.maxAdClicksPerSession-this.sessionData.adClicks)}sendSessionCompletionMessage(){chrome.runtime.sendMessage({action:"sessionCompleted",sessionData:this.sessionData}).catch(()=>{})}exportSessionData(){return{...this.sessionData,exportTime:(new Date).toISOString(),sessionDuration:this.getSessionDuration(),progress:this.getSessionProgress()}}resetSession(){this.sessionData={id:this.sessionId,startTime:Date.now(),postsRead:0,adClicks:0,totalReadingTime:0,pagesVisited:[],personalityType:null,deviceType:null,riskLevel:"low",status:"active"},this.saveSessionData()}cleanup(){this.monitoringInterval&&clearInterval(this.monitoringInterval),this.autoSaveInterval&&clearInterval(this.autoSaveInterval),this.forceNavigationInterval&&clearInterval(this.forceNavigationInterval),this.saveSessionData()}}